method derivative(xs: seq<int>) returns (result: seq<int>)
    requires |xs| > 0 // The input list must have at least one coefficient
    ensures |result| == |xs| - 1 // The output list will have one less coefficient than the input
    ensures forall i :: 0 <= i < |result| ==> result[i] == xs[i + 1] * (i + 1) // Each coefficient in the result is calculated correctly
{
    var n := |xs|;
    var res := new int[n - 1]; // Create an array for the result
    var i := 0;

    while i < n - 1
        invariant 0 <= i <= n - 1 // i is within bounds
        invariant |res| == n - 1 // The result array has the correct size
    {
        res[i] := xs[i + 1] * (i + 1); // Calculate the derivative coefficient
        i := i + 1; // Move to the next coefficient
    }

    result := res; // Assign the result to the output variable
}
```

